from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    k = len(alphabet)
    if not banned:
        return pow(k, n, MOD)

    char_idx = {c: i for i, c in enumerate(alphabet)}
    trie = [[-1] * k]
    bad = [False]

    for s in banned:
        node = 0
        for ch in s:
            c = char_idx[ch]
            if trie[node][c] == -1:
                trie[node][c] = len(trie)
                trie.append([-1] * k)
                bad.append(False)
            node = trie[node][c]
        bad[node] = True

    fail = [0] * len(trie)
    q = deque()
    for c in range(k):
        if trie[0][c] != -1:
            q.append(trie[0][c])
        else:
            trie[0][c] = 0

    while q:
        u = q.popleft()
        bad[u] = bad[u] or bad[fail[u]]
        for c in range(k):
            v = trie[u][c]
            if v != -1:
                fail[v] = trie[fail[u]][c]
                q.append(v)
            else:
                trie[u][c] = trie[fail[u]][c]

    good = [i for i, is_bad in enumerate(bad) if not is_bad]
    good_idx = {u: idx for idx, u in enumerate(good)}
    m = len(good)

    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(good):
        for c in range(k):
            v = trie[u][c]
            if not bad[v]:
                mat[i][good_idx[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for p in range(m):
                aip = ai[p]
                if aip:
                    bp = b[p]
                    for j in range(m):
                        ri[j] += aip * bp[j]
            for j in range(m):
                ri[j] %= MOD
        return res

    def vec_mul(v: list[int], a: list[list[int]]) -> list[int]:
        res = [0] * m
        for i in range(m):
            vi = v[i]
            if vi:
                ai = a[i]
                for j in range(m):
                    res[j] += vi * ai[j]
        return [x % MOD for x in res]

    vec = [0] * m
    vec[0] = 1
    exp = n
    while exp > 0:
        if exp & 1:
            vec = vec_mul(vec, mat)
        exp >>= 1
        if exp:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
